B.M2=new A.a4(58305,"MaterialIcons",!1)
B.KO=new A.O("tickets","Packed Suitcase","storage",0,"A suitcase at the bottom of a crate, initialled G.C. Inside: a spare collar and two one-way train tickets to Biscotti Bay for tonight \u2014 \u201cMr. G. Cracker\u201d and \u201cMiss T. Misu\u201d.",B.M2,B.bh,"crates",B.k,B.c,!1,null)
